INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen von Angeboten ein wichtiger Bestandteil der Kundenkommunikation?', 2, '[{"text": "Ja", "correct": true, "because": "Legt Projektbasis fest"}, {"text": "Nein", "correct": false, "because": "Es ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Erstellen von Angeboten?', 3, '[{"text": "Kundenbedarf mit Lösungen verbinden", "correct": true, "because": "Fördert Zustimmung"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Team intern koordinieren", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Angebote klären Kosten und Leistungen. b) Sie werden nur im Abschluss erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, früh nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Angebot?', 4, '[{"text": "Leistungsbeschreibung", "correct": true, "because": "Definiert Umfang"}, {"text": "Unklare Kosten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Kostenaufstellung", "correct": true, "because": "Zeigt Preis"}, {"text": "Zeitrahmen", "correct": true, "because": "Gibt Zeitplan"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Angebot starten?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit über Leistung fehlt"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Erstellen von Angeboten?', 3, '[{"text": "Kunden überzeugt und informiert", "correct": true, "because": "Fördert Zustimmung"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Team täglich steuern", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen von Angeboten nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Projektleiter beim Erstellen von Angeboten?', 3, '[{"text": "Angebot mit Team abstimmen", "correct": true, "because": "Sichert Machbarkeit"}, {"text": "Kosten allein festlegen", "correct": false, "because": "Geschäftsleitung"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Durchführungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Angebote basieren auf Kundenbedarf. b) Sie sind immer unverbindlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft verbindlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Angebot?', 3, '[{"text": "Unklare Erwartungen beim Kunden", "correct": true, "because": "Fehlende Basis"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Unklarheit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Angebot ohne Kundenbedarf erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Bedarf ist Grundlage"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Angebotselement?', 3, '[{"text": "Serverinstallation für 5.000 €", "correct": true, "because": "Konkret und klar"}, {"text": "Irgendwas anbieten", "correct": false, "because": "Zu vage"}, {"text": "Team soll etwas tun", "correct": false, "because": "Kein Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen von Angeboten nur für den Projektstart relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Primär vor Projektbeginn"}, {"text": "Nein", "correct": false, "because": "Kann auch später angepasst werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein gutes Angebot?', 4, '[{"text": "Klare Leistungsbeschreibung", "correct": true, "because": "Fördert Verständnis"}, {"text": "Unklare Kosten", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Realistischer Zeitrahmen", "correct": true, "because": "Zeigt Planung"}, {"text": "Transparente Preise", "correct": true, "because": "Sichert Vertrauen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Angebot dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Vertrag"}, {"text": "Nein", "correct": false, "because": "Dokumentation wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft beim Erstellen von Angeboten?', 3, '[{"text": "Angebotssoftware", "correct": true, "because": "Strukturiert Daten"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unprofessionell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Angebot ohne Kundenfeedback erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Bedarf unklar"}, {"text": "Ja", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Erstellen von Angeboten?', 3, '[{"text": "Unklare Kundenanforderungen", "correct": true, "because": "Verhindern Klarheit"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Struktur"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Angebote fördern Kundenvertrauen. b) Sie sind nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Erstellens von Angeboten?', 3, '[{"text": "Klarheit über Projektumfang", "correct": true, "because": "Fördert Zustimmung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Kundenbindung", "correct": false, "because": "Fördert Vertrauen"}]');
